#include "complex_numbers.h"

#include <cmath>

namespace complex_numbers {

complex_number::complex_number(double real, double imaginary)
    : real_(real), imaginary_(imaginary) {
}

double complex_number::real_part() const {
    return real_;
}

double complex_number::imaginary_part() const {
    return imaginary_;
}

complex_number complex_number::operator+(const complex_number& other) const {
    return complex_number(real_ + other.real_, imaginary_ + other.imaginary_);
}

complex_number complex_number::operator-(const complex_number& other) const {
    return complex_number(real_ - other.real_, imaginary_ - other.imaginary_);
}

complex_number complex_number::operator*(const complex_number& other) const {
    return complex_number(
        real_ * other.real_ - imaginary_ * other.imaginary_,
        real_ * other.imaginary_ + imaginary_ * other.real_);
}

complex_number complex_number::operator/(const complex_number& other) const {
    const double denominator =
        other.real_ * other.real_ + other.imaginary_ * other.imaginary_;

    return complex_number(
        (real_ * other.real_ + imaginary_ * other.imaginary_) / denominator,
        (imaginary_ * other.real_ - real_ * other.imaginary_) / denominator);
}

complex_number complex_number::conjugate() const {
    return complex_number(real_, -imaginary_);
}

double complex_number::abs() const {
    return std::hypot(real_, imaginary_);
}

double complex_number::absolute_value() const {
    return abs();
}

complex_number complex_number::exp() const {
    const double real_exponential = std::exp(real_);

    return complex_number(
        real_exponential * std::cos(imaginary_),
        real_exponential * std::sin(imaginary_));
}

complex_number complex_number::exponential() const {
    return exp();
}

bool operator==(const complex_number& lhs, const complex_number& rhs) {
    return lhs.real_part() == rhs.real_part() &&
           lhs.imaginary_part() == rhs.imaginary_part();
}

bool operator!=(const complex_number& lhs, const complex_number& rhs) {
    return !(lhs == rhs);
}

}  // namespace complex_numbers
